/**
 * dsh-provider-usage — 趋势查询路由（server/ui-routes 域趋势块，
 * #768 D12 由 domain2/routes/ui.ts 迁入，零行为变更）。
 *
 * 本块回答「趋势窗口怎么算/查」：clampTrendN（n 封顶纯函数）+ handleTrend
 *（provider 面 / 目录面双查询面，形状归一，非法参数回退不 400 的既有语义保持）。
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import { guardLoopbackMethod, writeJson } from "../../../../../shared/host-utils.js";
import { ADAPTER_CONTRACT_VERSION } from "../../shared/interface.ts";
import { TREND_DIR_MAX } from "../shared/interface.ts";
import type { UiRoutesContext } from "./context.ts";

// 趋势形状就地派生：本块只经 UiRoutesContext.trend 与聚合面打交道，粒度 / 指标 / 堆叠点
// 三种形状从它既有方法的签名反推即可，不必为同一形状另开一条跨域 type 引用边
//（#732 E3：纯重构不抬高 dir-imports 结构计数）。
type TrendService = UiRoutesContext["trend"];
type TrendGranularity = Parameters<TrendService["dirStacked"]>[1];
type TrendMetric = Parameters<TrendService["dirStacked"]>[2];
type TrendStackPoint = ReturnType<TrendService["dirStacked"]>["series"][number];

const TREND_WINDOW: Record<string, number> = { day: 30, week: 12, month: 12 };

/** 趋势指标白名单（键集即 {@link TrendMetric}；承担类型收窄见 isTrendMetric）。 */
const TREND_METRICS = new Set<string>([
  "total",
  "input",
  "output",
  "cacheRead",
  "cacheWrite",
  "calls",
]);

/** 指标白名单判定（承担类型收窄：白名单外的值一律回落 "total"）。 */
function isTrendMetric(value: string): value is TrendMetric {
  return TREND_METRICS.has(value);
}

export function clampTrendN(
  raw: string | null,
  gran: "day" | "week" | "month",
  retention: number,
): number {
  const cap =
    gran === "day"
      ? retention
      : gran === "week"
        ? Math.ceil(retention / 7)
        : Math.ceil(retention / 30);
  const parsed = raw === null || raw === "" ? NaN : Number(raw);
  const n = Number.isInteger(parsed) && parsed > 0 ? parsed : (TREND_WINDOW[gran] ?? 30);
  return Math.min(n, cap);
}

/** 趋势查询参数归一结果（非法值回退不 400——既有语义保持）。 */
interface TrendQuery {
  granularity: TrendGranularity;
  metric: TrendMetric;
  provider: string | undefined;
  dir: string | undefined;
  /** 全目录拆段面（dir 过滤优先：dir 存在时恒 false）。 */
  byDirAll: boolean;
  byModel: boolean;
  n: number;
  /** 是否走目录维度查询面（dir 过滤或 byDir=1）。 */
  byDir: boolean;
}

/**
 * 查询参数归一（纯函数）：
 * - granularity 白名单（week/month，其余回落 day）；
 * - metric 白名单（外回落 total）；
 * - provider 非空且 ≤128 字符，否则 undefined（全 provider 聚合）；
 * - 可选目录过滤：非空且不超数据层上限（TREND_DIR_MAX，与 isValidDirKey 同一事实源）
 *   按目录键过滤（basename 净化值或未识别桶键）；未传/非法（空串/超长）→ undefined =
 *   全目录聚合。原硬编码 128 与数据层 256 不一致——129–256 字符的合法目录键会被静默
 *   降级为「全目录聚合」（查询面悄然变形，且原 smoke 用例把这个错误行为锁死）。
 * - byDir=1 = 全目录拆段查询面（未传 dir 时按目录拆段 + dirs 全集图例，支撑趋势面板
 *   「打开即见目录分布」与目录筛选下拉候选）；不带该参数时走既有两分支。
 */
export function parseTrendQuery(url: URL, retentionDays: number): TrendQuery {
  const granularity = parseGranularity(url.searchParams.get("granularity"));
  const rawMetric = url.searchParams.get("metric") ?? "total";
  const metric: TrendMetric = isTrendMetric(rawMetric) ? rawMetric : "total";
  const provider = boundedParam(url.searchParams.get("provider"), 128);
  const dir = boundedParam(url.searchParams.get("dir"), TREND_DIR_MAX);
  // dir 与 provider 面分流：传 dir → 目录维度查询面；未传 → provider 维度
  // 原查询面（provider/byModel 参数语义原样保留，响应形状零变化）。
  // dir 过滤优先于 byDir（过滤面已隐含目录维度）；目录面与 provider 面互斥
  // （dir 行无 provider 关联，既定数据边界）。
  const byDirAll = dir === undefined && url.searchParams.get("byDir") === "1";
  const byModel = url.searchParams.get("byModel") === "1";
  return {
    granularity,
    metric,
    provider,
    dir,
    byDirAll,
    byModel,
    n: clampTrendN(url.searchParams.get("n"), granularity, retentionDays),
    byDir: dir !== undefined || byDirAll,
  };
}

/** 粒度白名单（week/month，其余含缺省回落 day）。 */
function parseGranularity(raw: string | null): TrendGranularity {
  return raw === "week" || raw === "month" ? raw : "day";
}

/** 有界查询参数：非空且不超上限才生效，否则 undefined（= 不过滤；非法不 400）。 */
function boundedParam(raw: string | null, max: number): string | undefined {
  const value = raw ?? "";
  return value.length > 0 && value.length <= max ? value : undefined;
}

/** 目录面与 provider 面的 stack 形状归一（两分支字段并集）。 */
type TrendStack = {
  series: TrendStackPoint[];
  providers: Array<{ provider: string; model: string | null }>;
  dirs: Array<{ dir: string }>;
};

/**
 * 查询面分发：目录面与 provider 面二选一。
 * 未过滤分支响应含 providers 图例（现状形状零变化），过滤分支含 dirs 目录图例。
 * byDir=1 全目录面加性附 providers 候选——默认请求恒带 byDir=1 时目录面
 * providers 恒空致适配器下拉无可选项（交互回归）；
 * 候选与 provider 面图例同源（seriesStacked 窗口内 distinct），series 不受影响
 * （dir 行无 provider 关联的既定数据边界不变，加性返回不破坏「未传参数零变化」）。
 * dir 过滤面保持空 providers（既有形状，过滤面选中态下适配器已互斥清空）。
 */
function buildTrendStack(trend: TrendService, query: TrendQuery): TrendStack {
  const { n, granularity, metric, provider, dir, byModel, byDir, byDirAll } = query;
  if (byDir) {
    const dirStack = trend.dirStacked(n, granularity, metric, dir);
    return {
      ...dirStack,
      providers: byDirAll
        ? trend.seriesStacked(n, granularity, metric, undefined, false).providers
        : [],
    };
  }
  return { ...trend.seriesStacked(n, granularity, metric, provider, byModel), dirs: [] };
}

export function handleTrend(
  req: IncomingMessage,
  res: ServerResponse,
  context: UiRoutesContext,
): void {
  if (!guardLoopbackMethod(req, res, ["GET"], { remoteAdmission: context.remoteAdmission })) return;
  const { statsService, trend } = context;
  const url = new URL(req.url ?? "/", "http://localhost");
  const retentionDays = statsService.config.trendRetentionDays;
  const query = parseTrendQuery(url, retentionDays);
  const { granularity, metric, provider, dir, byModel, byDirAll, byDir, n } = query;
  const stack = buildTrendStack(trend, query);
  const summary = byDir
    ? trend.dirWindowSummary(n, granularity, metric, dir, stack.series)
    : trend.windowSummary(n, granularity, metric, provider, byModel ? undefined : stack.series);

  writeJson(res, 200, {
    ok: true,
    plugin: "dsh-provider-usage",
    version: ADAPTER_CONTRACT_VERSION,
    granularity,
    metric,
    provider: provider ?? null,
    // 目录过滤回显（null = 未过滤 = 现状形状）；dirs 由 stack
    // 归一形状携带（过滤分支 = 窗口内目录图例，含未识别桶；dir 落盘即 basename
    // 净化值，无路径分隔符）。byDir=1 全目录面回显 byDir=true。
    // 回显实际生效面——byDirAll 定义含 dir === undefined 守卫（dir 优先
    // 于 byDir），同传 dir+byDir 时 byDir 回显 false、dir 回显生效键（客户端以
    // 回显驱动控件选中态，虚假 true 会误导恢复逻辑；smoke 同传用例固化）。
    dir: dir ?? null,
    byDir: byDirAll,
    byModel,
    n,
    retentionDays,
    ...stack,
    summary,
    firstDay: trend.firstRecordedDay(),
    generatedAt: Date.now(),
  });
}

/**
 * dsh-provider-usage — UI 配置读写路由（server/ui-routes 域 UI 配置块，
 * #768 D12 由 domain2/routes/ui.ts 迁入，零行为变更）。
 *
 * 本块回答「胶囊位置配置怎么读写」：GET 读内存权威，POST 归一化后串行写盘 +
 * 内存 + SSE 广播（广播扇出由组合根经 UiRoutesContext 注入，见 ./context.ts，
 * 本块只调用不实现）。
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import {
  guardLoopbackMethod,
  readJsonBodyOutcome,
  writeJson,
} from "../../../../../shared/host-utils.js";
import { normalizeUiConfig, writeUiConfig } from "../../shared/interface.ts";
import type { UiRoutesContext } from "./context.ts";

export async function handleUiConfig(
  req: IncomingMessage,
  res: ServerResponse,
  context: UiRoutesContext,
): Promise<void> {
  if (
    !guardLoopbackMethod(req, res, ["GET", "POST"], {
      remoteAdmission: context.remoteAdmission,
    })
  )
    return;
  const { statsService, uiConfig, broadcastUiConfigChanged } = context;

  if (req.method === "GET") {
    writeJson(res, 200, { ok: true, ui: uiConfig });
    return;
  }

  const outcome = await readJsonBodyOutcome(req);
  if (outcome.kind !== "json") return writeJson(res, 400, { error: "bad-json" });
  const body = outcome.value as Record<string, unknown>;

  const next = normalizeUiConfig(body);
  Object.assign(uiConfig, next);
  try {
    await writeUiConfig(statsService.historyRoot, uiConfig);
  } catch {
    return writeJson(res, 500, { error: "persist-failed" });
  }
  broadcastUiConfigChanged();
  writeJson(res, 200, { ok: true, ui: uiConfig });
}

/**
 * dsh-provider-usage — ui 路由装配形状与创建面（server/ui-routes 域，
 * #768 D12 由 domain2/routes/ui.ts 迁入，零行为变更）。
 *
 * 本文件是域内跨块值文件（四特征块 health/trend/ui-config/events 共享的装配形状，
 * 与 server/aggregate/index.ts 的 TrendTracker 组合根同形）：UiRoutesContext
 * 深封装（「路由 context 类」，与 server/pipeline 的 StatsServiceCtor 同形，
 * #768 D13 表述对齐）+ createUiRoutes 路由装配器。目录外（apply 装配）
 * 只经构造入口装配依赖并交给 createUiRoutes；字段保持只读、无行为逻辑；
 * 特征块经 `import type` 取用本形状
 * （类型边，运行时无环：本文件按值引用四块，四块只按类型引用本文件）。
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import type { UiPlacementConfig } from "../../shared/interface.ts";
import type { LayerErrorSurface } from "../shared/interface.ts";
import type { StatsService } from "../pipeline/interface.ts";
import type { TrendTracker } from "../aggregate/interface.ts";
import { handleHealth } from "./health.ts";
import { handleTrend } from "./trend.ts";
import { handleUiConfig } from "./ui-config.ts";
import { handleEvents } from "./events.ts";

/** 官方 connection 短请求 admission 的最小结构面；具体实现由组合根一次注入。 */
export type RemoteAdmissionSource = () =>
  ((request: IncomingMessage) => 401 | 403 | undefined) | undefined;

/** 官方 PeerScope 中 UI 长连接只需绑定的 Cordis 生命周期面。 */
export interface RemotePeerScope {
  readonly ctx: {
    effect(execute: () => () => void, label?: string): unknown;
  };
}

/** 官方 connection 长连接 admission 的最小结构面。 */
export type RemotePeerAdmissionSource = () =>
  | ((
      request: IncomingMessage,
    ) => { readonly peer: RemotePeerScope } | { readonly rejection: 401 | 403 })
  | undefined;

/** UiRoutesContext 依赖装配形状（路由 context 类的构造入口）。 */
export interface UiRoutesContextOptions {
  statsService: StatsService;
  trend: TrendTracker;
  uiConfig: UiPlacementConfig;
  sseClients: Set<ServerResponse>;
  broadcastUiConfigChanged: () => void;
  /** 域2每层错误面：health 响应 per-layer 段数据源。 */
  layerErrors: LayerErrorSurface;
  /** 非回环请求实时查询官方 connection admission；缺席时 shared guard fail-closed。 */
  remoteAdmission?: RemoteAdmissionSource;
  /** SSE 长连接专用：保留官方 PeerScope 并把关闭登记到 Peer 生命周期。 */
  remotePeerAdmission?: RemotePeerAdmissionSource;
}

/**
 * 路由 context 类（深封装）：把路由依赖收敛为类实例，目录外只经构造
 * 入口装配后交给 createUiRoutes；字段保持只读、无行为逻辑（只做面）。
 */
export class UiRoutesContext {
  readonly statsService: StatsService;
  readonly trend: TrendTracker;
  readonly uiConfig: UiPlacementConfig;
  readonly sseClients: Set<ServerResponse>;
  readonly broadcastUiConfigChanged: () => void;
  readonly layerErrors: LayerErrorSurface;
  readonly remoteAdmission?: RemoteAdmissionSource;
  readonly remotePeerAdmission?: RemotePeerAdmissionSource;

  constructor(opts: UiRoutesContextOptions) {
    this.statsService = opts.statsService;
    this.trend = opts.trend;
    this.uiConfig = opts.uiConfig;
    this.sseClients = opts.sseClients;
    this.broadcastUiConfigChanged = opts.broadcastUiConfigChanged;
    this.layerErrors = opts.layerErrors;
    this.remoteAdmission = opts.remoteAdmission;
    this.remotePeerAdmission = opts.remotePeerAdmission;
  }
}

export function createUiRoutes(
  routes: { health: string; trend: string; uiConfig: string; events: string },
  context: UiRoutesContext,
): WebRoute[] {
  return [
    {
      kind: "exact",
      path: routes.health,
      handler: (req, res) => handleHealth(req, res, context),
    },
    {
      kind: "exact",
      path: routes.trend,
      handler: (req, res) => handleTrend(req, res, context),
    },
    {
      kind: "exact",
      path: routes.uiConfig,
      handler: (req, res) => handleUiConfig(req, res, context),
    },
    {
      kind: "exact",
      path: routes.events,
      handler: (req, res) => handleEvents(req, res, context),
    },
  ];
}

/**
 * dsh-provider-usage — SSE 事件通道（server/ui-routes 域 SSE 块，
 * #768 D12 由 domain2/routes/ui.ts 迁入，零行为变更）。
 *
 * 本块回答「事件通道怎么开关」：连通帧 + 注册 + close 移除。通道是非可靠的——
 * 断线期间的广播帧直接丢失，重连只收新连通帧、无补帧（重连语义见 e2e
 * smoke「events 非可靠」用例；补帧出口不存在，由组合根测试的块出口清单锁定）。
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import {
  admitLongLivedRequest,
  bindPeerLifecycle,
  writeJson,
} from "../../../../../shared/host-utils.js";
import type { UiRoutesContext } from "./context.ts";

export function handleEvents(
  req: IncomingMessage,
  res: ServerResponse,
  context: UiRoutesContext,
): void {
  const admission = admitLongLivedRequest(req, {
    remotePeerAdmission: context.remotePeerAdmission,
  });
  if ("rejection" in admission) {
    writeJson(res, admission.rejection, {
      error: admission.rejection === 401 ? "unauthorized" : "forbidden: loopback-only",
    });
    return;
  }
  if (req.method !== "GET") {
    writeJson(res, 405, { error: `method not allowed: ${req.method}` });
    return;
  }
  const { sseClients } = context;

  let closed = false;
  let responseClosed = false;
  let peerEnded = false;
  let disposePeer: (() => void) | undefined;
  const removeStream = (): void => {
    if (closed) return;
    closed = true;
    sseClients.delete(res);
  };
  const closeForPeer = (): void => {
    removeStream();
    if (responseClosed) return;
    if (!res.writableEnded && !res.destroyed) res.destroy();
  };
  res.on("close", () => {
    responseClosed = true;
    removeStream();
    const dispose = disposePeer;
    disposePeer = undefined;
    if (!peerEnded) dispose?.();
  });
  if (admission.peer !== undefined) {
    try {
      disposePeer = bindPeerLifecycle(
        admission.peer,
        () => {
          peerEnded = true;
          closeForPeer();
        },
        "dsh-provider-usage: raw SSE bound to admitted Peer",
      );
    } catch {
      if (!res.headersSent) writeJson(res, 403, { error: "forbidden: peer-unavailable" });
      return;
    }
  }

  res.writeHead(200, {
    "content-type": "text/event-stream",
    "cache-control": "no-cache",
    connection: "keep-alive",
  });
  res.write(": connected\n\n");
  sseClients.add(res);
  res.on("close", () => {
    sseClients.delete(res);
  });
}

/**
 * dsh-provider-usage — 健康检查路由（server/ui-routes 域健康块，
 * #768 D12 由 domain2/routes/ui.ts 迁入，零行为变更）。
 *
 * 本块回答「系统健康吗」：适配器快照 + 域2每层错误面（aggregate/schedule/execute
 * 三层计数 + 最近 N 条，经 UiRoutesContext.layerErrors 注入读取，见 ./context.ts）。
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import { basename } from "node:path";
import { guardLoopbackMethod, writeJson } from "../../../../../shared/host-utils.js";
import { ADAPTER_CONTRACT_VERSION } from "../../shared/interface.ts";
import type { UiRoutesContext } from "./context.ts";

export function handleHealth(
  req: IncomingMessage,
  res: ServerResponse,
  context: UiRoutesContext,
): void {
  if (!guardLoopbackMethod(req, res, ["GET"], { remoteAdmission: context.remoteAdmission })) return;
  const { statsService, trend } = context;
  const snap = statsService.registry.snapshot();

  writeJson(res, 200, {
    ok: true,
    plugin: "dsh-provider-usage",
    version: ADAPTER_CONTRACT_VERSION,
    provider: statsService.config.provider,
    cacheSize: statsService.cacheSize(),
    adapters: snap.infos.map((i) => ({
      name: i.name,
      label: i.label,
      providers: i.providers,
      source: i.source,
      enabled: i.enabled,
      file: i.file !== undefined ? basename(i.file) : undefined,
    })),
    enabled: snap.enabled,
    errors: snap.errors,
    // 取数失败面（#1163）：与 errors（适配器加载/执行登记）并列，成功取数即清除。
    fetchErrors: statsService.fetchErrors(),
    historyDir: statsService.historyRoot,
    // 域2每层错误面：aggregate/schedule/execute 三层计数 + 最近 N 条；
    // 与 errors（域1 适配器最近一次登记）并列，字段风格一致（camelCase 平铺）。
    layerErrors: context.layerErrors.snapshot(),
    trend: trend.stats(),
  });
}

